"""Model client factory for jailbreak-zero."""

from __future__ import annotations

import os

from jailbreak_zero.models.fake import FakeModelClient
from jailbreak_zero.models.openai_compat import OpenAICompatibleModelClient
from jailbreak_zero.schemas import ExperimentConfig, ModelConfig


def _resolve_vllm(model: ModelConfig) -> OpenAICompatibleModelClient:
    if model.model_id in ("draft-model", "judge-model"):
        persona = "draft" if model.model_id == "draft-model" else "judge"
        prefix = persona.upper()
        base_url = os.environ.get(f"VDB_{prefix}_BASE_URL")
        api_key = os.environ.get(f"VDB_{prefix}_API_KEY", "EMPTY")
        if model.model_id == "draft-model":
            base_url = base_url or os.environ.get("VDB_DRAFT_BASE_URL", "http://127.0.0.1:8001/v1")
        else:
            base_url = base_url or os.environ.get("VDB_JUDGE_BASE_URL", "http://127.0.0.1:8002/v1")
        timeout = 300.0 if model.model_id == "judge-model" else 60.0
        return OpenAICompatibleModelClient(
            model,
            api_key=api_key,
            base_url=base_url,
            timeout=timeout,
            seed=20260904 if model.model_id == "draft-model" else None,
        )
    base_url = os.environ.get(model.endpoint_env or "VDB_BASE_URL")
    return OpenAICompatibleModelClient(model, base_url=base_url)


def _resolve_api(model: ModelConfig) -> OpenAICompatibleModelClient:
    extra_body = None
    api_key = os.environ.get("DEEPSEEK_API_KEY") or os.environ.get("VDB_API_KEY", "EMPTY")
    base_url = os.environ.get(model.endpoint_env or "VDB_BASE_URL", "https://api.deepseek.com")
    if model.model_id.startswith("deepseek"):
        extra_body = {"thinking": {"type": "disabled"}}
    return OpenAICompatibleModelClient(
        model,
        api_key=api_key,
        base_url=base_url,
        extra_body=extra_body,
    )


def build_model_client(model: ModelConfig, generation: ExperimentConfig | None = None):
    if model.provider == "fake":
        return FakeModelClient(model.model_id)
    if model.provider == "vllm":
        client = _resolve_vllm(model)
        if generation is not None:
            client.temperature = generation.generation.temperature
            client.top_p = generation.generation.top_p
            client.max_tokens = generation.generation.max_tokens
        return client
    if model.provider == "api":
        client = _resolve_api(model)
        if generation is not None:
            client.temperature = generation.generation.temperature
            client.top_p = generation.generation.top_p
            client.max_tokens = generation.generation.max_tokens
        return client
    raise RuntimeError(f"Unsupported model provider: {model.provider}")

