from __future__ import annotations

from collections.abc import Sequence

from jailbreak_zero.judges.fake import FakeJudge
from jailbreak_zero.judges.vdriftbench import VdriftbenchJudge
from jailbreak_zero.schemas import Behavior, JudgeConfig


def build_judge(config: JudgeConfig, behaviors: Sequence[Behavior] | None = None):
    if config.judge_type == "fake":
        return FakeJudge(config.model_id)
    if config.judge_type == "vdriftbench":
        if not behaviors:
            raise ValueError("vdriftbench judge requires behavior metadata")
        return VdriftbenchJudge(config, behaviors)
    raise RuntimeError(f"Unsupported judge type: {config.judge_type}")

